  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C06"],
      "claim": "Artemisinin, the closest analogue by Morgan similarity (0.1791), has low oral bioavailability in humans; as a sesquiterpene lactone natural product with multiple lactones and poor solubility, this directly supports low F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Limonin, a complex polycyclic lactone natural product, shows poor oral bioavailability in humans, supporting low F for the similarly rigid, lactone-rich query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "8-Prenylnaringenin has low oral bioavailability in humans, indicating that complex polyphenolic/lactone natural products often have poor oral absorption, consistent with low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C35"],
      "claim": "Menogaril, an anthracycline, has an absolute oral bioavailability of 32±12%, above the 20% threshold; however, its large aromatic glycoside structure is very dissimilar to the query, limiting transferability.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a rigid, highly oxygenated polycyclic sesquiterpene lactone with multiple lactones and hydroxyls. The closest analogue artemisinin (Morgan 0.1791) has low oral bioavailability in humans, and other complex lactone natural products (limonin, 8-PN) also show poor oral absorption. Higher-F analogues are structurally dissimilar (anthracyclines, nucleosides, fibrates) and transfer poorly. Therefore low oral bioavailability (F<20%) is better supported.",
  "evidence_gaps": [
    "No direct experimental bioavailability data for the query molecule.",
    "Morgan similarities are low (0.14-0.18), limiting transferability of all evidence.",
    "Artemisinin records include some conflicting 'good' bioavailability reports, adding uncertainty."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

